<?php
require_once __DIR__.'/../config/db.php';require_once __DIR__.'/../includes/auth.php';requireLogin();require_once __DIR__.'/../includes/request_tracking.php';
nrSchema($conn);$actor=exActor($conn,(int)$_SESSION['user_id']);
if(!naEligible($actor)&&naRole($actor)!=='SUPER_ADMIN'){http_response_code(403);exit('Nursing access required.');}
header('Cache-Control: private, no-store');
$approvals=($_GET['view']??'')==='approvals';if($approvals&&!naApprovalAccess($actor)){http_response_code(403);exit('Approval access denied.');}
$history=($_GET['view']??'')==='history';if($history&&!naApprovalAccess($actor)){http_response_code(403);exit('History access denied.');}
$title=$approvals?'Requests for Approval':($history?'Request History':'My Requests');$error='';$detail=null;$items=[];$all=[];$notices=[];
function rtUrl(array $r): string {return 'my_requests.php?type='.rawurlencode($r['type']).'&id='.(int)($r['id']??$r['request_id']);}
try{
    if($_SERVER['REQUEST_METHOD']==='POST'){
        requireCsrfToken();
        if(isset($_POST['read_notices']))nsScheduleQuery($conn,"UPDATE nursing_document_notifications SET status='READ',reviewed_by=?,reviewed_at=NOW() WHERE employee_id=? AND status='UNREAD' AND (id IN (SELECT notification_id FROM nursing_service_request_notifications WHERE recipient_id=?) OR id IN (SELECT notification_id FROM nursing_exchange_notifications WHERE recipient_id=?))",[$actor['user_id'],$actor['user_id'],$actor['user_id'],$actor['user_id']]);
        elseif(isset($_POST['upload'])){
            $request=rtDetail($conn,$actor,'LEAVE',(int)($_POST['id']??0));
            nrUploadDocument($conn,$actor,(int)$request['id'],$_FILES['document']??[]);header('Location: '.rtUrl($request));exit;
        }else{
            $type=(string)($_POST['type']??'');$id=filter_var($_POST['id']??null,FILTER_VALIDATE_INT);$version=filter_var($_POST['version']??null,FILTER_VALIDATE_INT);
            $request=rtDetail($conn,$actor,$type,(int)$id);$decision=(string)($_POST['decision']??'');
            if($type==='EXCHANGE')exDecide($conn,$actor,(int)$id,(int)$version,$decision,trim($_POST['remarks']??''));
            else nrDecide($conn,$actor,['id'=>$id,'version'=>$version,'decision'=>$decision,'remarks'=>$_POST['remarks']??'']);
            header('Location: '.rtUrl($request));exit;
        }
        header('Location: my_requests.php');exit;
    }elseif($_SERVER['REQUEST_METHOD']!=='GET'){http_response_code(405);exit;}
    if(isset($_GET['id']))$detail=rtDetail($conn,$actor,(string)($_GET['type']??''),(int)$_GET['id']);
    $all=rtList($conn,$actor,$approvals,$history);$items=rtFilter($all,$_GET);$notices=rtNotices($conn,$actor);
}catch(Throwable $e){$known=$e instanceof DomainException||$e instanceof InvalidArgumentException||$e->getCode()===409;$error=$known?$e->getMessage():'Unable to load requests. Please try again.';http_response_code($e->getCode()===409?409:($e instanceof DomainException?403:($known?422:500)));if(!$known)error_log('Request tracking: '.$e->getMessage());}
$counts=array_fill_keys(['TOTAL','PENDING','APPROVED','REJECTED','CANCELLED'],0);foreach($all as $item){$counts['TOTAL']++;if(isset($counts[$item['status']]))$counts[$item['status']]++;}
$departments=[];$employees=[];foreach($all as $item){$departments[$item['department']]=$item['department'];$employees[$item['employee_id']]=$item['employee'];}
$page=max(1,(int)($_GET['page']??1));$pages=max(1,(int)ceil(count($items)/25));$page=min($page,$pages);$total=count($items);$items=array_slice($items,($page-1)*25,25);
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=h($title)?> | NURSYNC</title><?=nursingThemeAssets()?><link rel="stylesheet" href="../public/css/style.css"><link rel="stylesheet" href="../public/css/dashboard.css"><link rel="stylesheet" href="../public/css/module-theme.css?v=18"><link rel="stylesheet" href="../public/css/schedule-management.css"><link rel="stylesheet" href="../public/css/request-tracking.css?v=2"><script defer src="../public/js/sidebar.js"></script><script defer src="../public/js/nursync-ui.js?v=4"></script></head>
<body class="module-ui schedule-page request-tracking-page"><nav class="navbar"><div class="navbar-brand"><h1>NURSYNC</h1></div><div class="navbar-menu"><span class="user-info"><?=h($actor['name'])?></span></div></nav><div class="dashboard-container"><?php include __DIR__.'/../includes/schedule_sidebar.php';?><main class="main-content schedule-main">
<header class="schedule-heading"><div><p class="schedule-eyebrow">REQUEST MANAGEMENT</p><h2><?=h($title)?></h2><p><?=$approvals?'Review requests assigned to your current approval stage.':'Track your submitted nursing requests and approval status.'?></p></div><div class="schedule-actions"><a class="btn btn-light" href="my_requests.php">My Requests</a><?php if(naApprovalAccess($actor)):?><a class="btn btn-light" href="?view=approvals">Requests for Approval</a><a class="btn btn-light" href="?view=history">Request History</a><?php endif;?><a class="btn btn-primary" href="request_application.php?kind=LEAVE&amp;view=new">New request</a></div></header>
<?php if($error):?><p class="schedule-notice" role="alert"><?=h($error)?></p><?php endif;?>
<section class="rt-metrics" aria-label="Request totals"><?php foreach($counts as $key=>$count):?><article><span><?=h(ucfirst(strtolower($key)))?> Requests</span><strong><?=$count?></strong></article><?php endforeach;?></section>
<?php if($notices):?><details class="rt-panel rt-notifications"><summary><?=count($notices)?> unread request notifications</summary><?php foreach($notices as $notice):?><a href="<?=h(rtUrl(['type'=>$notice['type'],'id'=>$notice['request_id']]))?>"><?=h($notice['message'])?><small><?=h($notice['created_at'])?></small></a><?php endforeach;?><form method="post"><input type="hidden" name="csrf_token" value="<?=h(csrfToken())?>"><button class="btn btn-light" name="read_notices" value="1">Mark request notifications as read</button></form></details><?php endif;?>
<?php if($detail):$r=$detail['row'];$exchange=$detail['type']==='EXCHANGE';?>
<section class="rt-panel" aria-labelledby="requestDetailTitle"><header class="rt-detail-header"><div><p class="schedule-eyebrow">REQUEST DETAILS</p><h3 id="requestDetailTitle"><?=h($detail['number'])?></h3></div><span class="rt-badge" data-status="<?=h($detail['status'])?>"><?=h($detail['label'])?></span></header>
<dl class="rt-facts"><?php foreach(['Employee'=>$detail['employee'],'Department'=>$detail['department'],'Request type'=>$exchange?'Exchange of Duty':($detail['type']==='OFF'?'Request-Off':'Leave / '.$r['leave_type']),'Date submitted'=>$detail['submitted'],'Requested dates'=>implode(', ',$detail['dates']),'Current approver'=>$detail['approver']] as $label=>$value):?><div><dt><?=h($label)?></dt><dd><?=h($value)?></dd></div><?php endforeach;?></dl>
<h4>Request reason</h4><p class="rt-text"><?=h($r['reason']?:'No reason recorded.')?></p><h4>Monthly schedule</h4><p><?=h(rtScheduleState($conn,$detail))?></p>
<?php if($exchange):$original=nsScheduleDecode($r['original_json']);$validation=nsScheduleDecode($r['validation_json']);?><h4>Duty exchange</h4><div class="rt-table-wrap"><table class="rt-table"><thead><tr><th>Employee</th><th>Original duty</th><th>Proposed duty</th></tr></thead><tbody><?php foreach($original as $index=>$cell):$other=$original[1-$index]??[];?><tr><td><?=h($cell['name']??'')?></td><td><?=h(($cell['date']??'').' / '.($cell['shift_label']??$cell['shift']??''))?></td><td><?=h(($other['date']??'').' / '.($other['shift_label']??$other['shift']??''))?></td></tr><?php endforeach;?></tbody></table></div>
<?php if(!empty($r['error_message'])):?><p class="schedule-notice" role="alert"><?=h($r['error_message'])?></p><?php endif;?>
<?php if(!empty($validation['monthly_hours'])):?><h4>Validated duty hours</h4><ul><?php foreach($validation['monthly_hours'] as $scheduleId=>$summaries)foreach($summaries as $summary):?><li><?=h(($validation['periods'][$scheduleId]??'Affected month').' / '.rtNames($conn,[(int)$summary['employee_id']]).': '.$summary['hours'].' scheduled hours / '.$summary['target'].' reference hours')?></li><?php endforeach;?></ul><p>Minimum rest: <?=(int)($validation['minimum_rest']??0)?> hours. Final approval validates both schedules again.</p><?php endif;?><?php endif;?>
<?php if($detail['type']==='LEAVE'):?><p class="schedule-notice">Nursing Service clearance and HR approval are separate. This system does not record formal HR approval.<?=$r['approval_method']==='AUTOMATIC_ROLE_EXEMPTION'?' Chief Nurse leave is exempt from internal review; no reviewer approval is implied.':''?></p><?php endif;?>
<h4>Required approval stages</h4><p><?=h(($exchange?'Other employee confirmation → ':'').implode(' → ',array_map(fn($s)=>str_replace('_',' ',$s[$exchange?'stage':'role']).(!empty($s['department'])?' / '.$s['department']:''),$detail['route']))?:'No internal review required.')?></p>
<h4>Approval history</h4><ol class="rt-timeline"><?php foreach($detail['events'] as $event):?><li><strong><?=h(str_replace('_',' ',$event['decision']))?></strong><time><?=h($event['created_at'])?></time><span><?=h($event['actor_name'].' / '.str_replace('_',' ',$event['actor_role']).' / Round '.$event['round_no'])?></span><?php if($event['remarks']!==''):?><p class="rt-text"><?=h($event['remarks'])?></p><?php endif;?></li><?php endforeach;?></ol>
<?php $canWithdraw=$exchange?((int)$actor['user_id']===(int)$r['requester_id']&&in_array($r['status'],array_merge(['DRAFT','RETURNED_FOR_CORRECTION'],NS_EXCHANGE_PENDING),true)):nrCanWithdraw($conn,$actor,$r);$canAccept=$exchange&&(int)$actor['user_id']===(int)$r['partner_id']&&$r['status']==='PENDING_PARTNER_CONFIRMATION';$canReopen=$exchange&&naRole($actor)==='SUPER_ADMIN'&&$r['status']==='UPDATE_FAILED';if($detail['can_decide']||$canWithdraw||$canAccept||$canReopen):?>
<form method="post" class="schedule-form rt-decision"><input type="hidden" name="csrf_token" value="<?=h(csrfToken())?>"><input type="hidden" name="id" value="<?=$detail['id']?>"><input type="hidden" name="type" value="<?=h($detail['type'])?>"><input type="hidden" name="version" value="<?=(int)$r['version']?>"><label class="full">Decision remarks<textarea name="remarks" rows="3" maxlength="2000" id="rtRemarks"></textarea></label><p class="full">A reason is required when rejecting or declining. Decisions are recorded with your identity and server timestamp.</p><footer><?php foreach(($detail['can_decide']?['approve'=>'Approve','reject'=>'Reject']+(($exchange||$detail['type']==='LEAVE')?['return'=>'Return for correction']:[]):[])+($canAccept?['accept'=>'Accept exchange','decline'=>'Decline exchange']:[])+($canWithdraw?['withdraw'=>'Cancel request']:[])+($canReopen?['reopen'=>'Return failed update for correction']:[]) as $decision=>$label):?><button class="btn <?=$decision==='approve'?'btn-primary':'btn-light'?>" name="decision" value="<?=$decision?>" onclick="document.getElementById('rtRemarks').required=<?=in_array($decision,['reject','decline','return'],true)?'true':'false'?>"><?=h($label)?></button><?php endforeach;?></footer></form><?php endif;?>
<?php if(!$exchange&&nrCanEditRequest($actor,$r)):?><a class="btn btn-primary" href="request_application.php?kind=<?=h($detail['type'])?>&amp;id=<?=$detail['id']?>">Edit and resubmit</a><?php endif;?>
<?php if($exchange&&(int)$r['requester_id']===(int)$actor['user_id']&&in_array($r['status'],['DRAFT','RETURNED_FOR_CORRECTION'],true)):?><a class="btn btn-primary" href="exchange_application.php?view=new&amp;id=<?=$detail['id']?>">Edit and resubmit</a><?php endif;?>
<?php if($detail['type']==='LEAVE'):?><h4>Supporting documents</h4><?php foreach(exRows($conn,'SELECT id,original_name FROM nursing_request_supporting_documents WHERE request_id=?',[$detail['id']]) as $document):?><p><a href="request_application.php?document=<?=(int)$document['id']?>"><?=h($document['original_name'])?></a></p><?php endforeach;?>
<?php if(nrCanUploadDocument($actor,$r)):?><form method="post" enctype="multipart/form-data" class="schedule-form"><input type="hidden" name="csrf_token" value="<?=h(csrfToken())?>"><input type="hidden" name="id" value="<?=$detail['id']?>"><input type="hidden" name="upload" value="1"><label class="full">Supporting document (PDF, JPEG or PNG, up to 5 MB)<input name="document" type="file" accept="application/pdf,image/jpeg,image/png" required></label><button class="btn btn-light">Upload document</button></form><?php endif;?>
<?php if($r['status']==='APPROVED_FOR_HR_FILING'):?><a class="btn btn-light" href="request_application.php?kind=LEAVE&amp;id=<?=$detail['id']?>&amp;print=1">Print Internal Leave Approval Form</a><?php endif;?><?php endif;?></section><?php endif;?>
<section class="rt-panel"><form method="get" class="rt-filters" aria-label="Filter requests"><?php if($approvals||$history):?><input type="hidden" name="view" value="<?=$approvals?'approvals':'history'?>"><?php endif;?>
<?php foreach(['type'=>['Request Type',['OFF'=>'Request-Off','LEAVE'=>'Leave','EXCHANGE'=>'Exchange of Duty']],'status'=>['Status',['DRAFT'=>'Draft','PENDING'=>'Pending','APPROVED'=>'Approved / Cleared for HR Filing','REJECTED'=>'Rejected','CANCELLED'=>'Cancelled','RETURNED'=>'Returned for correction','ERROR'=>'Update failed']]]+($approvals||$history?['department'=>['Department',$departments],'employee_id'=>['Employee',$employees]]:[]) as $field=>[$label,$options]):?><label><?=h($label)?><select name="<?=$field?>"><option value="">All</option><?php foreach($options as $value=>$text):?><option value="<?=h($value)?>" <?=(string)($_GET[$field]??'')===(string)$value?'selected':''?>><?=h($text)?></option><?php endforeach;?></select></label><?php endforeach;?>
<?php foreach(['month'=>['Month and Year','month'],'from'=>['Requested from','date'],'to'=>['Requested through','date'],'q'=>['Request Number','search']] as $field=>[$label,$type]):?><label><?=h($label)?><input name="<?=$field?>" type="<?=$type?>" value="<?=h($_GET[$field]??'')?>" <?=$field==='q'?'maxlength="40"':''?>></label><?php endforeach;?><button class="btn btn-primary">Apply filters</button><a class="btn btn-light" href="my_requests.php<?=$approvals?'?view=approvals':($history?'?view=history':'')?>">Reset</a></form>
<p role="status"><?=$total?> matching request(s). Summary cards show all <?=$approvals?'assigned':($history?'authorized':'your')?> requests.</p>
<div class="rt-table-wrap"><table class="rt-table"><thead><tr><th>Request Number</th><th>Request Type</th><th>Requested Date</th><th>Date Submitted</th><th>Current Status</th><th>Current Approver</th><th>Actions</th></tr></thead><tbody><?php foreach($items as $item):?><tr><td data-label="Request Number"><strong><?=h($item['number'])?></strong><?php if($approvals):?><small><?=h($item['employee'].' / '.$item['department'])?></small><?php endif;?></td><td data-label="Request Type"><?=h(['OFF'=>'Request-Off','LEAVE'=>'Leave / '.($item['row']['leave_type']??''),'EXCHANGE'=>'Exchange of Duty'][$item['type']])?></td><td data-label="Requested Date"><?=h(implode(', ',$item['dates']))?></td><td data-label="Date Submitted"><?=h($item['submitted'])?></td><td data-label="Current Status"><span class="rt-badge" data-status="<?=h($item['status'])?>"><?=h($item['label'])?></span></td><td data-label="Current Approver"><?=h($item['approver'])?></td><td data-label="Actions"><a class="btn btn-light" href="<?=h(rtUrl($item))?>">View Details<span class="sr-only"> <?=h($item['number'])?></span></a></td></tr><?php endforeach;?></tbody></table></div><?php if(!$items):?><p class="rt-empty">No requests match these filters. Submit a request or adjust your filters.</p><?php endif;?>
<nav class="schedule-actions" aria-label="Request pages"><?php if($page>1):?><a class="btn btn-light" href="?<?=h(http_build_query(array_merge($_GET,['page'=>$page-1])))?>">Previous</a><?php endif;?><span>Page <?=$page?> of <?=$pages?></span><?php if($page<$pages):?><a class="btn btn-light" href="?<?=h(http_build_query(array_merge($_GET,['page'=>$page+1])))?>">Next</a><?php endif;?></nav></section>
</main></div></body></html>
